using UnityEngine;using UnityEngine.Rendering;using UnityEngine.Rendering.Universal;
namespace RailDrivingSimulator {
 public class Effects:MonoBehaviour {
  GameObject rain;Transform wiper;Light headlights;Volume volume;bool enabledRain;ColorAdjustments adaptation;float exposureBase;Camera viewCamera;float phase,probeClock;ReflectionProbe probe;
  public void Configure(Camera cam,bool wet,bool night,int quality){Cleanup();enabledRain=wet;var obj=new GameObject("风挡雨滴与雨幕",typeof(ParticleSystem));obj.transform.SetParent(cam.transform,false);obj.transform.localPosition=new Vector3(0,3,7);rain=obj;var ps=obj.GetComponent<ParticleSystem>();var main=ps.main;main.loop=true;main.startLifetime=1.0f;main.startSpeed=13;main.startSize=.012f;main.maxParticles=Game.Mobile?700:1500;main.simulationSpace=ParticleSystemSimulationSpace.Local;main.startColor=new Color(.7f,.8f,.85f,.12f);var emission=ps.emission;emission.rateOverTime=wet?(Game.Mobile?400:800):0;var shape=ps.shape;shape.shapeType=ParticleSystemShapeType.Box;shape.scale=new Vector3(12,.4f,14);obj.transform.localRotation=Quaternion.Euler(90,0,0);var renderer=ps.GetComponent<ParticleSystemRenderer>();renderer.renderMode=ParticleSystemRenderMode.Stretch;renderer.lengthScale=1.8f;renderer.velocityScale=.015f;renderer.material=new Material(Shader.Find("Universal Render Pipeline/Particles/Unlit"));var rm=renderer.sharedMaterial;rm.SetFloat("_Surface",1);rm.SetFloat("_Blend",0);rm.SetFloat("_SrcBlend",5);rm.SetFloat("_DstBlend",10);rm.SetFloat("_ZWrite",0);rm.SetFloat("_Cull",0);rm.EnableKeyword("_SURFACE_TYPE_TRANSPARENT");rm.renderQueue=3000;rain.SetActive(wet);
  var arm=GameObject.CreatePrimitive(PrimitiveType.Cube);Destroy(arm.GetComponent<Collider>());arm.name="雨刷";arm.transform.SetParent(cam.transform,false);arm.transform.localPosition=new Vector3(.33f,-.32f,1.06f);arm.transform.localScale=new Vector3(.016f,.45f,.016f);wiper=arm.transform;var m=new Material(Shader.Find("Universal Render Pipeline/Lit"));m.color=new Color(.03f,.035f,.04f);arm.GetComponent<Renderer>().sharedMaterial=m;
  headlights=new GameObject("前照灯",typeof(Light)).GetComponent<Light>();headlights.transform.SetParent(cam.transform,false);headlights.type=LightType.Spot;headlights.range=100;headlights.spotAngle=65;headlights.intensity=night?35:3;headlights.color=new Color(.93f,.96f,1);
  volume=new GameObject("色调与泛光",typeof(Volume)).GetComponent<Volume>();volume.isGlobal=true;volume.profile=ScriptableObject.CreateInstance<VolumeProfile>();var tone=volume.profile.Add<Tonemapping>();tone.mode.Override(TonemappingMode.ACES);var bloom=volume.profile.Add<Bloom>();bloom.intensity.Override(quality>0?.15f:0);bloom.threshold.Override(1.25f);var exposure=volume.profile.Add<ColorAdjustments>();adaptation=exposure;exposureBase=night?.2f:0;viewCamera=cam;exposure.postExposure.Override(exposureBase);var additional=cam.GetUniversalAdditionalCameraData();additional.renderPostProcessing=true;
  if(wet&&quality>0){probe=new GameObject("雨天地面反射",typeof(ReflectionProbe)).GetComponent<ReflectionProbe>();probe.transform.SetParent(cam.transform,false);probe.transform.localPosition=new Vector3(0,1.7f,0);probe.cullingMask=~(1<<8);probe.mode=ReflectionProbeMode.Realtime;probe.refreshMode=ReflectionProbeRefreshMode.ViaScripting;probe.timeSlicingMode=ReflectionProbeTimeSlicingMode.IndividualFaces;probe.resolution=Game.Mobile?(quality>=3?128:64):(quality>=2?256:128);probe.size=Vector3.one*15000;probe.boxProjection=false;probe.farClipPlane=Game.Mobile?200:450;probe.hdr=true;probeClock=13;}
  }
  public void Tick(RunState state,bool external,float dt){if(adaptation&&viewCamera&&dt>0){float sunFacing=Vector3.Dot(viewCamera.transform.forward,Shader.GetGlobalVector("_RailSunDirection"));float target=exposureBase-Mathf.SmoothStep(0,.15f,Mathf.InverseLerp(.6f,1,sunFacing));adaptation.postExposure.value=Mathf.Lerp(adaptation.postExposure.value,target,1-Mathf.Exp(-dt*1.2f));}if(wiper){wiper.gameObject.SetActive(!external&&enabledRain);phase+=dt*(state.wiper?2.5f:0);wiper.localRotation=Quaternion.Euler(0,0,state.wiper?Mathf.Sin(phase)*65:65);}if(headlights)headlights.enabled=state.lights;if(probe){probeClock+=dt;if(probeClock>(Game.Mobile?25:12)){probeClock=0;probe.RenderProbe();}}}
  void OnDestroy(){Cleanup();}
  public void Cleanup(){enabledRain=false;if(rain){rain.SetActive(false);var ps=rain.GetComponent<ParticleSystem>();if(ps)ps.Stop(true,ParticleSystemStopBehavior.StopEmittingAndClear);}if(wiper)wiper.gameObject.SetActive(false);if(headlights)headlights.enabled=false;if(volume)volume.enabled=false;if(probe)probe.enabled=false;if(rain){var r=rain.GetComponent<ParticleSystemRenderer>();if(r&&r.sharedMaterial)Destroy(r.sharedMaterial);Destroy(rain);}if(wiper){var r=wiper.GetComponent<Renderer>();if(r&&r.sharedMaterial)Destroy(r.sharedMaterial);Destroy(wiper.gameObject);}if(headlights)Destroy(headlights.gameObject);if(volume){if(volume.profile)Destroy(volume.profile);Destroy(volume.gameObject);}if(probe)Destroy(probe.gameObject);}
 }
}
